"""Small, privacy-conscious client for OpenAI's Responses API.

Only Python's standard library is required.  Prompt text is sent in the HTTPS
request body and is never logged by this module.  Responses are requested with
``store=False`` by default.

Example::

    from openai_client import send_prompt

    answer = send_prompt("Explain quaternions in one paragraph.")
    print(answer)

Set ``OPENAI_API_KEY`` in the environment before calling :func:`send_prompt`,
or pass ``api_key=...`` explicitly.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Mapping, Optional


RESPONSES_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-5-mini"


class OpenAIError(RuntimeError):
    """An error returned by OpenAI or an invalid API response."""

    def __init__(
        self,
        message: str,
        *,
        status: Optional[int] = None,
        code: Optional[str] = None,
        request_id: Optional[str] = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.request_id = request_id


def _response_text(response: Mapping[str, Any]) -> str:
    """Extract assistant text from a Responses API response object."""
    output_text = response.get("output_text")
    if isinstance(output_text, str):
        return output_text

    pieces = []
    output = response.get("output", [])
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping) or item.get("type") != "message":
                continue
            content = item.get("content", [])
            if not isinstance(content, list):
                continue
            for part in content:
                if not isinstance(part, Mapping):
                    continue
                if part.get("type") in ("output_text", "text"):
                    text = part.get("text")
                    if isinstance(text, str):
                        pieces.append(text)

    if pieces:
        return "".join(pieces)
    raise OpenAIError("OpenAI returned no text output")


def _api_error(error: urllib.error.HTTPError) -> OpenAIError:
    """Create a concise exception without retaining the full response body."""
    request_id = error.headers.get("x-request-id") if error.headers else None
    message = f"OpenAI API request failed with HTTP {error.code}"
    api_code = None
    try:
        body = json.loads(error.read().decode("utf-8"))
        details = body.get("error", {}) if isinstance(body, dict) else {}
        if isinstance(details, dict):
            if isinstance(details.get("message"), str):
                message = details["message"]
            if isinstance(details.get("code"), str):
                api_code = details["code"]
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        pass
    return OpenAIError(
        message, status=error.code, code=api_code, request_id=request_id
    )


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: Optional[str] = None,
    timeout: float = 60.0,
    instructions: Optional[str] = None,
    max_output_tokens: Optional[int] = None,
) -> str:
    """Send private text to the Responses API and return its text output.

    The request explicitly sets ``store`` to ``False``.  This limits API-side
    application-state storage; it does not alter OpenAI's platform data
    retention policies.  The function performs no logging and no automatic
    retries, so a failed request is not silently submitted again.

    Args:
        prompt: Text to send to the model.
        model: OpenAI model ID.
        api_key: API key. If omitted, ``OPENAI_API_KEY`` is used.
        timeout: Network timeout in seconds.
        instructions: Optional developer/system guidance for the response.
        max_output_tokens: Optional positive response-token limit.
    """
    if not isinstance(prompt, str):
        raise TypeError("prompt must be a string")
    if not isinstance(model, str) or not model.strip():
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    if instructions is not None and not isinstance(instructions, str):
        raise TypeError("instructions must be a string or None")
    if max_output_tokens is not None and (
        isinstance(max_output_tokens, bool)
        or not isinstance(max_output_tokens, int)
        or max_output_tokens <= 0
    ):
        raise ValueError("max_output_tokens must be a positive integer or None")

    key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError(
            "Missing API key: set OPENAI_API_KEY or pass api_key explicitly"
        )
    if "\r" in key or "\n" in key:
        raise ValueError("api_key must not contain newline characters")

    payload: dict[str, Any] = {
        "model": model.strip(),
        "input": prompt,
        "store": False,
    }
    if instructions is not None:
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        payload["max_output_tokens"] = max_output_tokens

    request = urllib.request.Request(
        RESPONSES_URL,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read()
            request_id = response.headers.get("x-request-id")
    except urllib.error.HTTPError as error:
        raise _api_error(error) from None
    except urllib.error.URLError as error:
        # Do not include request content or credentials in the exception.
        raise OpenAIError(f"Could not reach OpenAI: {error.reason}") from None

    try:
        decoded = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise OpenAIError(
            "OpenAI returned invalid JSON", request_id=request_id
        ) from error
    if not isinstance(decoded, dict):
        raise OpenAIError(
            "OpenAI returned an unexpected response", request_id=request_id
        )
    try:
        return _response_text(decoded)
    except OpenAIError as error:
        if error.request_id is None:
            error.request_id = request_id
        raise


__all__ = ["DEFAULT_MODEL", "OpenAIError", "send_prompt"]
